with enriched as (select *, ntile(10) over w_hist as amount_bucket, round(amount / sum(amount) over (partition by order_id, status), 4) as amount_share, dense_rank() over w_grp as amount_dense_rank from payments window w_hist as (order by amount, id), w_grp as (partition by order_id order by amount nulls first)) select date_trunc('month', paid_at) as activity_month, method, date_trunc('week', paid_at) as week_start, sum(case when method = 'paypal' then amount_share else 0 end) as paypal_amount_share, round(sum(amount) / nullif(count(case when status = 'SUCCESS' then 1 end), 0), 2) as amount_per_success, count_if(method = 'promptpay') as promptpay_events from enriched group by grouping sets ((date_trunc('month', paid_at), method, date_trunc('week', paid_at)), (date_trunc('month', paid_at), method)) having sum(case when method = 'paypal' then amount_share else 0 end) < 0;
